challenge_result.investigation_instruction:
{
  "plans": [
    {
      "hypothesis_id": "h1",
      "hypothesis_statement": "The primary cause of the outage is that the HSS (pyhss) container has exited, breaking the IMS authentication and registration flow.",
      "primary_suspect_nf": "pyhss",
      "probes": [
        {
          "tool": "get_network_status",
          "args_hint": "Check status of all network functions.",
          "expected_if_hypothesis_holds": "The 'pyhss' container is reported with a status of 'exited' or another non-running state.",
          "falsifying_observation": "The 'pyhss' container is reported as 'running'.",
          "conflates_with": []
        },
        {
          "tool": "check_process_listeners",
          "args_hint": "container='pyhss'",
          "expected_if_hypothesis_holds": "The command fails or returns an empty list, as a container that has exited will have no active processes listening on network ports.",
          "falsifying_observation": "The command returns a list of active listeners for the pyhss container, indicating that the HSS process is running and bound to its service ports (e.g., Diameter port 3868).",
          "conflates_with": []
        },
        {
          "tool": "query_subscriber",
          "args_hint": "imsi='<any_valid_imsi>'",
          "expected_if_hypothesis_holds": "The tool fails to connect to the HSS and returns an error, as the service is down.",
          "falsifying_observation": "The tool successfully retrieves subscriber information, proving the HSS is running, reachable, and functionally responding to requests.",
          "conflates_with": []
        }
      ],
      "notes": "The hypothesis points to a complete failure of the HSS. The selected probes aim to falsify this by checking three distinct aspects of the service: the container's reported status, the presence of a listening process, and the application-level functionality. The IMS registration flow ('ims_registration', steps 4, 6, 7) and Diameter authentication ('diameter_cx_authentication') depend entirely on the HSS being responsive. A successful result from any of these probes would strongly contradict the hypothesis."
    }
  ]
}
